INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-w1-verified-seamless-textures-vol1', 'ws-artemis-store', 'asset-w1-verified-seamless-textures-vol1', 'verified-seamless-textures-vol1', '검증된 심리스 텍스처 Vol.1 (7종)', '1024² 심리스 텍스처 7종 묶음으로, 오디트 심리스 판정은 SEAMLESS 5종 · SOFT-SEAM 2종이며 7종 전부 오디트 PASS다. 밉 포함 GPU 메모리 합계는 37.33MB / 40MB 예산 (93.3%) — vol1-final.audit.json, --strict 통과로 실측됐고, 항목마다 거리 밴드(5·15·30 m)별 대비 보존율과 판독성 등급표가 붙는다. 각 항목에 luna 생성 기록(프롬프트·모델·요청 해시·sha256)과 오디트 리포트를 동봉한다 — 심리스와 판독성을 실측 증거로 제시하는 것이 이 팩의 차별점이다.', 190000, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
